        </svg>
      </button>
      <h1>إتمام الطلب</h1>
    </header>

    <main>
      <!-- Item 1 -->
      <div class="item" data-price="5">
        <div class="photo-placeholder"></div>
        <div class="item-details">
          <div class="item-name">تفاحة طازجة</div>
          <div class="quantity-stepper">
            <button class="stepper-btn minus">-</button>
            <span class="quantity"><bdi dir="ltr">2</bdi></span>
            <button class="stepper-btn plus">+</button>
          </div>
          <div class="item-price"><bdi>10.00 د.إ</bdi></div>
        </div>
      </div>

      <!-- Item 2 -->
      <div class="item" data-price="12">
        <div class="photo-placeholder"></div>
        <div class="item-details">
          <div class="item-name">حليب طازج</div>
          <div class="quantity-stepper">
            <button class="stepper-btn minus">-</button>
            <span class="quantity"><bdi dir="ltr">1</bdi></span>
            <button class="stepper-btn plus">+</button>
          </div>
          <div class="item-price"><bdi>12.00 د.إ</bdi></div>
        </div>
      </div>

      <!-- Item 3 -->
      <div class="item" data-price="4">
        <div class="photo-placeholder"></div>
        <div class="item-details">
          <div class="item-name">خبز أرز</div>
          <div class="quantity-stepper">
            <button class="stepper-btn minus">-</button>
            <span class="quantity"><bdi dir="ltr">3</bdi></span>
            <button class="stepper-btn plus">+</button>
          </div>
          <div class="item-price"><bdi>12.00 د.إ</bdi></div>
        </div>
      </div>
    </main>

    <!-- Promo code -->
    <section class="promo">
      <input type="text" placeholder="أدخل رمز الخصم" dir="ltr">
      <button>تطبيق</button>
    </section>

    <!-- Summary -->
    <section class="summary">
      <div class="summary-row subtotal">
        <span>المجموع الفرعي</span>
        <span><bdi>34.00 د.إ</bdi></span>
      </div>
      <div class="summary-row delivery">
        <span>معدل التوصيل</span>
        <span><bdi>10.00 د.إ</bdi></span>
      </div>
      <div class="summary-row vat">
        <span>ضريبة القيمة المضافة (5%)</span>
        <span><bdi>2.20 د.إ</bdi></span>
      </div>
      <div class="summary-row total">
        <span>الإجمالي</span>
        <span><bdi>46.20 د.إ</bdi></span>
      </div>
    </section>

    <!-- Place order button -->
    <button class="place-order">إتمام الطلب</button>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', function() {
      const items = document.querySelectorAll('.item');
      const deliveryFee = 10;
      const vatRate = 0.05;

      function formatAED(amount) {
        const formatted = amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
        return `<bdi>${formatted} د.إ</bdi>`;
      }

      function updateItemPrice(item) {
        const price = parseFloat(item.dataset.price);
        const qty = parseInt(item.querySelector('.quantity bdi').textContent, 10);
        const total = price * qty;
        item.querySelector('.item-price').innerHTML = formatAED(total);
      }

      function updateSummary() {
        let subtotal = 0;
        items.forEach(item => {
          const price = parseFloat(item.dataset.price);
          const qty = parseInt(item.querySelector('.quantity bdi').textContent, 10);
          subtotal += price * qty;
        });

        const vat = (subtotal + deliveryFee) * vatRate;
        const total = subtotal + deliveryFee + vat;

        document.querySelector('.summary-row.subtotal span:last-child').innerHTML = formatAED(subtotal);
        document.querySelector('.summary-row.delivery span:last-child').innerHTML = formatAED(deliveryFee);
        document.querySelector('.summary-row.vat span:last-child').innerHTML = formatAED(vat);
        document.querySelector('.summary-row.total span:last-child').innerHTML = formatAED(total);
      }

      items.forEach(item => {
        const minusBtn = item.querySelector('.stepper-btn.minus');
        const plusBtn = item.querySelector('.stepper-btn.plus');
        const qtyBdi = item.querySelector('.quantity bdi');

        minusBtn.addEventListener('click', function() {
          let qty = parseInt(qtyBdi.textContent, 10);
          if (qty > 1) {
            qty--;
            qtyBdi.textContent = qty;
            updateItemPrice(item);
            updateSummary();
          }
        });

        plusBtn.addEventListener('click', function() {
          let qty = parseInt(qtyBdi.textContent, 10);
          qty++;
          qtyBdi.textContent = qty;
          updateItemPrice(item);
          updateSummary();
        });
      });

      // Initial calculation
      items.forEach(updateItemPrice);
      updateSummary();
    });
  </script>
</body>
</html>
